function parseObject(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) return value;
  if (Array.isArray(value)) value = value.map((part) => typeof part === "string" ? part : (part?.text ?? part?.content ?? "")).join("\n");
  const text = String(value ?? "").trim(); const candidates = [text];
  for (const match of text.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)) candidates.push(match[1].trim());
  let depth = 0; let start = -1; let inString = false; let escaped = false;
  for (let i = 0; i < text.length; i++) { const char = text[i]; if (inString) { if (escaped) escaped = false; else if (char === "\\") escaped = true; else if (char === "\"") inString = false; continue; } if (char === "\"") { inString = true; continue; } if (char === "{") { if (depth === 0) start = i; depth++; } else if (char === "}" && depth > 0) { depth--; if (depth === 0 && start >= 0) candidates.push(text.slice(start, i + 1)); } }
  for (let i = candidates.length - 1; i >= 0; i--) { try { const parsed = JSON.parse(candidates[i]); if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed; } catch {} }
  throw new Error("Nemotron response does not contain a valid JSON object");
}
const parsed = parseObject($json.choices?.[0]?.message?.content ?? $json.text ?? $json.output ?? $json);
const stringValue = (name, min, max) => { const value = String(parsed[name] ?? "").trim(); if (value.length < min || value.length > max) throw new Error(`Invalid ${name} in Nemotron response`); return value; };
const listValue = (name, maxLength) => { if (!Array.isArray(parsed[name]) || parsed[name].length < 1 || parsed[name].length > 5) throw new Error(`Invalid ${name} in Nemotron response`); const values = parsed[name].map((value) => String(value).trim()); if (values.some((value) => value.length < 3 || value.length > maxLength) || new Set(values).size !== values.length) throw new Error(`Invalid ${name} in Nemotron response`); return values; };
return { json: { output: { summary: stringValue("summary", 40, 1200), recommended_formats: listValue("recommended_formats", 160), recommended_hooks: listValue("recommended_hooks", 220), risks: listValue("risks", 220), monetization_notes: listValue("monetization_notes", 220) } } };
